with open('/tmp/yt_data.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Search for attributedDescription in the structure
def find_desc(obj, path=''):
    if isinstance(obj, dict):
        if 'attributedDescription' in obj:
            print(f'Found at: {path}')
            print(json.dumps(obj['attributedDescription'], ensure_ascii=False)[:2000])
            return
        for k, v in obj.items():
            find_desc(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            find_desc(v, f'{path}[{i}]')

find_desc(data)
